import * as THREE from 'three';

const STATE = { PATROL: 0, ALERT: 1, COMBAT: 2, HUNT: 3, DEAD: 4 };

const _ray = new THREE.Raycaster();
const _dir = new THREE.Vector3();
const _fwd = new THREE.Vector3();

let skinMat, vestMat, clothMat, gunMat;
function materials() {
  if (skinMat) return;
  skinMat  = new THREE.MeshStandardMaterial({ color: 0xb08868, roughness: 0.8 });
  vestMat  = new THREE.MeshStandardMaterial({ color: 0x2e3328, roughness: 0.85 });
  clothMat = new THREE.MeshStandardMaterial({ color: 0x44483b, roughness: 0.9 });
  gunMat   = new THREE.MeshStandardMaterial({ color: 0x1c1d1f, roughness: 0.5, metalness: 0.55 });
}

export class Enemy {
  constructor(scene, spawn) {
    materials();
    this.scene = scene;
    this.state = STATE.PATROL;
    this.hp = 100;
    this.waypoints = spawn.waypoints.map(([x, z]) => new THREE.Vector3(x, 0, z));
    this.wpIndex = 0;
    this.yaw = Math.random() * Math.PI * 2;
    this.targetYaw = this.yaw;
    this.visionTimer = Math.random() * 0.15;
    this.reactionTimer = 0;
    this.loseSightTimer = 0;
    this.burstLeft = 0;
    this.fireTimer = 1 + Math.random();
    this.lastKnown = null;
    this.deathT = 0;
    this.hitboxes = [];

    this.group = new THREE.Group();
    this.group.position.set(spawn.pos[0], 0, spawn.pos[1]);
    this.buildBody();
    scene.add(this.group);
  }

  buildBody() {
    const g = this.group;
    const add = (geo, mat, x, y, z, part) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.castShadow = true;
      m.userData.enemy = this;
      m.userData.part = part;
      g.add(m);
      if (part) this.hitboxes.push(m);
      return m;
    };
    // legs
    add(new THREE.BoxGeometry(0.16, 0.85, 0.18), clothMat, -0.11, 0.425, 0, 'body');
    add(new THREE.BoxGeometry(0.16, 0.85, 0.18), clothMat, 0.11, 0.425, 0, 'body');
    // torso + plate carrier
    add(new THREE.BoxGeometry(0.42, 0.55, 0.24), clothMat, 0, 1.12, 0, 'body');
    add(new THREE.BoxGeometry(0.46, 0.4, 0.3), vestMat, 0, 1.12, 0, 'body');
    // arms
    add(new THREE.BoxGeometry(0.11, 0.5, 0.13), clothMat, -0.27, 1.15, 0, 'body');
    this.rightArm = add(new THREE.BoxGeometry(0.11, 0.45, 0.13), clothMat, 0.27, 1.18, -0.12, 'body');
    // head + helmet
    this.head = add(new THREE.BoxGeometry(0.2, 0.22, 0.2), skinMat, 0, 1.52, 0, 'head');
    add(new THREE.BoxGeometry(0.24, 0.13, 0.24), vestMat, 0, 1.6, 0, 'head');
    // rifle held forward
    this.gun = add(new THREE.BoxGeometry(0.05, 0.07, 0.62), gunMat, 0.13, 1.3, -0.3, null);
    this.muzzle = new THREE.Object3D();
    this.muzzle.position.set(0.13, 1.3, -0.62);
    g.add(this.muzzle);
    // muzzle flash light (off by default)
    this.flash = new THREE.PointLight(0xffb066, 0, 7, 2);
    this.flash.position.copy(this.muzzle.position);
    g.add(this.flash);
  }

  get position() { return this.group.position; }
  get headPos() {
    return this.head.getWorldPosition(new THREE.Vector3());
  }
  get alive() { return this.state !== STATE.DEAD; }

  canSee(playerEye, solids, fovCheck = true) {
    const eye = this.headPos;
    _dir.copy(playerEye).sub(eye);
    const dist = _dir.length();
    if (dist > 30) return false;
    _dir.normalize();
    if (fovCheck) {
      _fwd.set(Math.sin(this.yaw), 0, Math.cos(this.yaw));
      const flat = _dir.clone().setY(0).normalize();
      if (_fwd.dot(flat) < Math.cos(THREE.MathUtils.degToRad(60))) return false; // 120° FOV
    }
    _ray.set(eye, _dir);
    _ray.far = dist - 0.2;
    return _ray.intersectObjects(solids.children, false).length === 0;
  }

  // Called when the player fires anywhere nearby.
  hearGunshot(playerPos) {
    if (!this.alive) return;
    if (this.position.distanceTo(playerPos) < 26 && this.state === STATE.PATROL) {
      this.lastKnown = playerPos.clone();
      this.state = STATE.HUNT;
    }
  }

  takeDamage(amount, playerPos) {
    if (!this.alive) return false;
    this.hp -= amount;
    this.lastKnown = playerPos.clone();
    if (this.hp <= 0) {
      this.state = STATE.DEAD;
      this.deathT = 0;
      this.flash.intensity = 0;
      return true; // killed
    }
    if (this.state !== STATE.COMBAT) {
      this.state = STATE.COMBAT;
      this.reactionTimer = 0.25;
    }
    return false;
  }

  moveToward(target, speed, dt, colliders) {
    _dir.copy(target).sub(this.position).setY(0);
    const dist = _dir.length();
    if (dist < 0.4) return true;
    _dir.normalize();
    this.targetYaw = Math.atan2(_dir.x, _dir.z);
    const step = Math.min(speed * dt, dist);
    const nx = this.position.x + _dir.x * step;
    const nz = this.position.z + _dir.z * step;
    if (!this.collides(nx, this.position.z, colliders)) this.position.x = nx;
    if (!this.collides(this.position.x, nz, colliders)) this.position.z = nz;
    return false;
  }

  collides(x, z, colliders) {
    const r = 0.35;
    for (const box of colliders) {
      if (x + r > box.min.x && x - r < box.max.x &&
          z + r > box.min.z && z - r < box.max.z &&
          box.min.y < 1.5 && box.max.y > 0.2) return true;
    }
    return false;
  }

  update(dt, ctx) {
    // ctx: { playerEye, playerPos, solids, colliders, fireAtPlayer, time }
    if (this.state === STATE.DEAD) {
      // fall over sideways
      this.deathT = Math.min(1, this.deathT + dt * 2.6);
      const t = this.deathT;
      this.group.rotation.z = (Math.PI / 2) * t * t;
      this.group.position.y = -0.15 * t;
      return;
    }

    // smooth turn
    let dy = this.targetYaw - this.yaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    this.yaw += dy * Math.min(1, dt * 7);
    this.group.rotation.y = this.yaw;

    this.flash.intensity *= Math.pow(0.0001, dt); // fast decay

    // vision check at 8 Hz
    this.visionTimer -= dt;
    let seesPlayer = false;
    if (this.visionTimer <= 0) {
      this.visionTimer = 0.125;
      seesPlayer = this.canSee(ctx.playerEye, ctx.solids, this.state !== STATE.COMBAT);
      this._sees = seesPlayer;
    } else {
      seesPlayer = this._sees;
    }

    switch (this.state) {
      case STATE.PATROL: {
        const wp = this.waypoints[this.wpIndex];
        if (this.moveToward(wp, 1.5, dt, ctx.colliders)) {
          this.wpIndex = (this.wpIndex + 1) % this.waypoints.length;
        }
        this.animateLegs(ctx.time, 1.5);
        if (seesPlayer) {
          this.state = STATE.ALERT;
          this.reactionTimer = 0.35 + Math.random() * 0.25;
          this.lastKnown = ctx.playerPos.clone();
        }
        break;
      }
      case STATE.ALERT: {
        this.targetYaw = this.yawTo(ctx.playerPos);
        this.reactionTimer -= dt;
        if (!seesPlayer) { this.state = STATE.HUNT; break; }
        if (this.reactionTimer <= 0) this.state = STATE.COMBAT;
        break;
      }
      case STATE.COMBAT: {
        this.targetYaw = this.yawTo(ctx.playerPos);
        if (seesPlayer) {
          this.lastKnown = ctx.playerPos.clone();
          this.loseSightTimer = 0;
          this.combatFire(dt, ctx);
        } else {
          this.loseSightTimer += dt;
          if (this.loseSightTimer > 2.5) this.state = STATE.HUNT;
        }
        break;
      }
      case STATE.HUNT: {
        if (seesPlayer) {
          this.state = STATE.COMBAT;
          this.lastKnown = ctx.playerPos.clone();
          break;
        }
        if (!this.lastKnown || this.moveToward(this.lastKnown, 2.6, dt, ctx.colliders)) {
          this.state = STATE.PATROL;
        }
        this.animateLegs(ctx.time, 2.6);
        break;
      }
    }
  }

  yawTo(p) {
    return Math.atan2(p.x - this.position.x, p.z - this.position.z);
  }

  animateLegs(time, speed) {
    const swing = Math.sin(time * speed * 4) * 0.3;
    this.group.children[0].rotation.x = swing;
    this.group.children[1].rotation.x = -swing;
  }

  combatFire(dt, ctx) {
    this.fireTimer -= dt;
    if (this.fireTimer > 0) return;
    if (this.burstLeft <= 0) {
      this.burstLeft = 3 + Math.floor(Math.random() * 3);
    }
    this.burstLeft--;
    this.fireTimer = this.burstLeft > 0 ? 0.11 : 0.7 + Math.random() * 0.8;

    const dist = this.position.distanceTo(ctx.playerPos);
    // hit probability falls with range
    const hitChance = Math.max(0.04, 0.32 - dist * 0.008);
    const hit = Math.random() < hitChance;
    this.flash.intensity = 22;
    ctx.fireAtPlayer(this, hit, dist);
  }

  dispose() {
    this.scene.remove(this.group);
  }
}
